package com.mcschool.flashcard.lessons;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import tools.jackson.databind.ObjectMapper;

/**
 * Homework-specific checks on the canonical lessonJson generated by
 * WorkbookContentService. This class does NOT generate or render lesson content.
 */
final class PostLessonHomeworkCanonicalAdapter {
    private PostLessonHomeworkCanonicalAdapter() {}

    record Reviewed(Map<String,Object> review, Map<String,Object> diversity,
                    boolean hasGraphTask) {}

    @SuppressWarnings("unchecked")
    static Reviewed inspect(ObjectMapper mapper, WorkbookContentService.Content authored,
            Map<String,Object> lessonEvidence) throws Exception {
        if(authored==null || authored.lessonJson()==null)
            throw new IllegalArgumentException("HOMEWORK_CANONICAL_CONTENT_MISSING");
        Map<String,Object> document=mapper.readValue(authored.lessonJson(),Map.class);
        if(!(document.get("workbookPages") instanceof List<?> pages) || pages.size()!=1
                || !(pages.get(0) instanceof Map<?,?> page)
                || !(page.get("blocks") instanceof List<?> blocks))
            throw new IllegalArgumentException("HOMEWORK_CANONICAL_PAGE_INVALID");
        if(!(document.get("qa") instanceof Map<?,?> qa)
                || !(qa.get("algebra") instanceof List<?> checks))
            throw new IllegalArgumentException("HOMEWORK_CANONICAL_QA_MISSING");

        List<Map<String,Object>> tasks=new ArrayList<>();
        List<Map<?,?>> taskBlocks=new ArrayList<>();
        collectTaskBlocks(blocks,taskBlocks,0);
        boolean hasGraph=false;
        for(Map<?,?> block:taskBlocks) {
            String type=Objects.toString(block.get("type"),"");
            int number=taskNumber(block.get("number"));
            Map<?,?> assertion=matchingAssertion(checks,number);
            String expression;
            if("visualTask".equals(type)) {
                if(!(block.get("spec") instanceof Map<?,?> spec))
                    throw new IllegalArgumentException("HOMEWORK_CANONICAL_VISUAL_MISSING");
                hasGraph |= "graph".equals(spec.get("type"));
                // Viewport/language changes alone are not new mathematics.
                Map<String,Object> fingerprint=new LinkedHashMap<>();
                spec.forEach((key,value)->fingerprint.put(String.valueOf(key),value));
                fingerprint.remove("xRange");fingerprint.remove("yRange");fingerprint.remove("language");
                expression="visual:"+digest(canonical(fingerprint).toString());
            }else{
                expression=Objects.toString(assertion.get("expression"),"");
                if(expression.isBlank())expression=Objects.toString(assertion.get("equation"),"");
                if(expression.isBlank())
                    throw new IllegalArgumentException("HOMEWORK_CANONICAL_EXPRESSION_MISSING");
                expression=PostLessonHomeworkSeriesDiversity.key(expression);
            }
            if(expression.isBlank())
                throw new IllegalArgumentException("HOMEWORK_CANONICAL_TASK_MISSING");
            Map<String,Object> task=new LinkedHashMap<>();
            task.put("title",shortText(block.get("title"),145));
            task.put("description",shortText(block.get("description"),200));
            task.put("expression",shortText(expression,200));
            tasks.add(task);
        }
        if(tasks.isEmpty() || tasks.size()>2)
            throw new IllegalArgumentException("HOMEWORK_CANONICAL_TASK_COUNT");
        Map<String,Object> summary=new LinkedHashMap<>();
        summary.put("topic",shortText(page.get("title"),88));
        summary.put("subtitle",shortText(page.get("subtitle"),120));
        summary.put("tasks",tasks);

        Map<String,Object> review=new LinkedHashMap<>(
                PostLessonHomeworkReviewMetadata.build(summary,lessonEvidence));
        review.put("generator","WORKBOOK_CANONICAL");
        // Staff-only. Never include source transcript or private answers in pupil PDF.
        review.put("sourceEvidenceNote",shortText(authored.lessonPlan(),1000));
        return new Reviewed(review,summary,hasGraph);
    }

    /** Same child-container traversal as McpHomeworkDraftValidator.countTasks. */
    private static void collectTaskBlocks(List<?> blocks,List<Map<?,?>> found,int depth) {
        if(depth>12)throw new IllegalArgumentException("HOMEWORK_CANONICAL_NESTING");
        for(Object raw:blocks) {
            if(!(raw instanceof Map<?,?> block))continue;
            String type=Objects.toString(block.get("type"),"");
            if("exercise".equals(type) || "visualTask".equals(type))
                found.add(block);
            for(String key:List.of("children","left","right"))
                if(block.get(key) instanceof List<?> nested)
                    collectTaskBlocks(nested,found,depth+1);
        }
    }

    private static int taskNumber(Object value){
        try{
            int number=Integer.parseInt(Objects.toString(value,"").trim());
            if(number<1 || number>2)throw new NumberFormatException();
            return number;
        }catch(NumberFormatException invalid){
            throw new IllegalArgumentException("HOMEWORK_CANONICAL_TASK_NUMBER",invalid);
        }
    }

    private static Map<?,?> matchingAssertion(List<?> checks,int number){
        for(Object candidate:checks) {
            if(candidate instanceof Map<?,?> assertion
                    && assertion.get("number") instanceof Number n && n.intValue()==number)
                return assertion;
        }
        throw new IllegalArgumentException("HOMEWORK_CANONICAL_QA_TASK_MISMATCH");
    }

    private static Object canonical(Object value){
        if(value instanceof Map<?,?> map){
            Map<String,Object> sorted=new TreeMap<>();
            for(Map.Entry<?,?> entry:map.entrySet())
                sorted.put(String.valueOf(entry.getKey()),canonical(entry.getValue()));
            return sorted;
        }
        if(value instanceof List<?> list)
            return list.stream().map(PostLessonHomeworkCanonicalAdapter::canonical).toList();
        return value;
    }

    private static String digest(String input){
        try{
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(input.getBytes(StandardCharsets.UTF_8)));
        }catch(Exception cause){
            throw new IllegalStateException("HOMEWORK_CANONICAL_DIGEST",cause);
        }
    }

    private static String shortText(Object value,int max){
        String str=Objects.toString(value,"").replaceAll("[\\r\\n\\t]+"," ").trim();
        return str.length()<=max?str:str.substring(0,max);
    }
}
